    private void showInitialMenu(){String start=project.getStartMenu();if(start==null||start.isBlank()||!project.getMenus().containsKey(start))startGame(null);else showMenu(start);}

    private boolean showMenu(String id){MenuScreen menu=project.getMenus().get(id);if(menu==null){logger.accept("[Menu] No existe la pantalla de menú '"+id+"'.");return false;}playing=false;textLayer.clear();audio.stopEffects();menuLayer.getChildren().clear();Pane board=new Pane();board.setPrefSize(menu.canvasWidth,menu.canvasHeight);board.setMinSize(menu.canvasWidth,menu.canvasHeight);board.setMaxSize(menu.canvasWidth,menu.canvasHeight);board.setStyle("-fx-background-color:"+css(menu.background)+";");if(!menu.backgroundAssetKey.isBlank()){ImageView iv=pixelAsset(menu.backgroundAssetKey,menu.canvasWidth,menu.canvasHeight,true);if(iv!=null)board.getChildren().add(iv);}Node title=menuTitle(menu);title.setLayoutX(menu.titleX);title.setLayoutY(menu.titleY);board.getChildren().add(title);for(MenuButton def:menu.buttons){Node button=menuButton(def);button.setLayoutX(def.x);button.setLayoutY(def.y);button.setCursor(Cursor.HAND);button.setOnMouseClicked(e->{if(!def.enabled){e.consume();return;}switch(def.action){case START_GAME->startGame(def.target);case OPEN_MENU->showMenu(def.target);case EXIT->{var w=getScene()==null?null:getScene().getWindow();if(w!=null)w.hide();}}e.consume();});board.getChildren().add(button);}DoubleBinding scale=Bindings.createDoubleBinding(()->{double raw=Math.min(menuLayer.getWidth()/Math.max(1,menu.canvasWidth),menuLayer.getHeight()/Math.max(1,menu.canvasHeight));if(project.getScaleMode()==ScaleMode.STRETCH)return Math.max(.05,raw);return raw>=1&&project.isIntegerScale()?Math.max(1,Math.floor(raw)):Math.max(.05,raw);},menuLayer.widthProperty(),menuLayer.heightProperty());board.scaleXProperty().bind(scale);board.scaleYProperty().bind(scale);menuLayer.getChildren().add(board);StackPane.setAlignment(board,Pos.CENTER);return true;}
    private ImageView pixelAsset(String key,double width,double height,boolean mouseTransparent){Asset a=project.getAssets().get(key);Image image=image(key);if(a==null||image==null)return null;ImageView iv=new ImageView(image);iv.setSmooth(a.filterMode==FilterMode.LINEAR);iv.setCache(false);iv.setPreserveRatio(false);iv.setFitWidth(Math.max(1,Math.rint(width)));iv.setFitHeight(Math.max(1,Math.rint(height)));iv.setMouseTransparent(mouseTransparent);if(a.isRegion())iv.setViewport(new Rectangle2D(a.regionX,a.regionY,a.regionWidth,a.regionHeight));return iv;}
