    private static Color fx(java.awt.Color c){return Color.rgb(c.getRed(),c.getGreen(),c.getBlue(),c.getAlpha()/255.0);}private static String css(java.awt.Color c){return String.format(Locale.ROOT,"rgba(%d,%d,%d,%.4f)",c.getRed(),c.getGreen(),c.getBlue(),c.getAlpha()/255.0);}

    private void startGame(String requestedScene){menuLayer.getChildren().clear();String scene=requestedScene==null||requestedScene.isBlank()?project.getStartLevel():requestedScene;if(!project.getLevels().containsKey(scene)){logger.accept("[Menu] La escena destino '"+scene+"' no existe; se usará la escena inicial.");scene=project.getStartLevel();}loadScene(scene,null,null);playing=true;requestFocus();}
    private void loadScene(String id,Double targetX,Double targetY){Level next=project.getLevels().get(id);if(next==null){logger.accept("[Runtime] No existe la escena '"+id+"'.");return;}audio.stopEffects();level=next;bodies.clear();particles.clear();contacts.clear();frameContacts.clear();scheduled.clear();textLayer.clear();runtimeSeconds=0;scheduledSequence=0;runtimeEntitySequence=0;cameraInitialized=false;shakeRemaining=shakeTotal=shakeIntensity=shakeX=shakeY=0;for(EntityDef def:level.entities){Body body=new Body(resolvePrefabInstance(def));normalizeHealth(body);normalizeGrid(body);bodies.put(def.id,body);}if(targetX!=null&&targetY!=null)bodies.values().stream().filter(this::isPlayerControlled).findFirst().ifPresent(b->{b.def.x=targetX;b.def.y=targetY;b.originX=targetX;b.originY=targetY;b.visualFromX=targetX;b.visualFromY=targetY;});compileWorldScripts();resolveInitialPenetrations();refreshContactSensors();updateCamera(0);fireWorld(ScriptProgram.Event.START);for(Body body:List.copyOf(bodies.values()))fire(body,ScriptProgram.Event.START,null);}
    private void compileWorldScripts(){sceneProgram=ScriptProgram.compile(level==null?"":level.script);layerPrograms.clear();if(level!=null)for(TileLayer l:level.tileLayers)layerPrograms.put(l.id,ScriptProgram.compile(l.script));}
    private void fireWorld(ScriptProgram.Event event){if(level==null)return;if(sceneProgram!=null&&sceneProgram.validation().valid())sceneProgram.fire(event,new WorldScriptContext(null));for(TileLayer l:level.tileLayers){ScriptProgram p=layerPrograms.get(l.id);if(p!=null&&p.validation().valid())p.fire(event,new WorldScriptContext(l));}}
    private void emit(String name,Body source,Body other){if(name==null||name.isBlank()||level==null)return;if(sceneProgram!=null&&sceneProgram.validation().valid())sceneProgram.fireEvent(name,new WorldScriptContext(null));for(TileLayer l:level.tileLayers){ScriptProgram p=layerPrograms.get(l.id);if(p!=null&&p.validation().valid())p.fireEvent(name,new WorldScriptContext(l));}for(Body b:List.copyOf(bodies.values())){ensureProgram(b);if(b.program!=null&&b.program.validation().valid())b.program.fireEvent(name,new ScriptContext(b,b==source?other:source));}}

    private void normalizeGrid(Body body){ComponentDef grid=activeComponent(body,"GridMovement");if(grid==null||!grid.bool("snap",true))return;double step=Math.max(.01,grid.number("step",1));body.def.x=Math.rint(body.def.x/step)*step;body.def.y=Math.rint(body.def.y/step)*step;body.visualFromX=body.def.x;body.visualFromY=body.def.y;}
    private void normalizeHealth(Body body){ComponentDef health=activeComponent(body,"Health");if(health==null)return;double max=Math.max(0,health.number("max",100)),current=Math.max(0,Math.min(max,health.number("current",max)));health.properties.put("max",number(max));health.properties.put("current",number(current));}

    private void update(double dt){if(level==null)return;runtimeSeconds+=Math.max(0,dt);runScheduledActions();frameContacts=new HashSet<>();for(Body b:bodies.values()){b.grounded=b.touchingLeft=b.touchingRight=b.touchingTop=false;}refreshContactSensors();fireWorld(ScriptProgram.Event.UPDATE);for(Body body:List.copyOf(bodies.values())){if(body.destroyed||!body.def.enabled)continue;applyBuiltins(body,dt);fire(body,ScriptProgram.Event.UPDATE,null);integrate(body,dt);updateAnimator(body,dt);updateParticles(body,dt);}checkEntityOverlaps();checkAnimationHitboxes();refreshContactSensors();applyTileSurfaceEffects(dt);contacts=frameContacts;bodies.values().removeIf(b->b.destroyed);updateParticleList(dt);updateCamera(dt);textLayer.update(runtimeSeconds);if(pendingScene!=null){PendingScene target=pendingScene;pendingScene=null;loadScene(target.id,target.x,target.y);}}
    private void runScheduledActions(){int guard=0;while(!scheduled.isEmpty()&&scheduled.peek().due<=runtimeSeconds+1e-9&&guard++<10000){ScheduledAction a=scheduled.poll();try{a.action.run();}catch(RuntimeException ex){logger.accept("[Script timer] "+ex.getMessage());}}if(guard>=10000)logger.accept("[Script timer] Se alcanzó el límite de acciones programadas en un frame.");}
    private void schedule(double seconds,Runnable action){if(action!=null)scheduled.add(new ScheduledAction(runtimeSeconds+Math.max(0,seconds),++scheduledSequence,action));}

    private void applyBuiltins(Body body,double dt){
        ComponentDef grid=activeComponent(body,"GridMovement"),controller=activeComponent(body,"PlayerController"),platformer=activeComponent(body,"PlatformerController");
        if(grid!=null){body.vx=0;body.vy=0;applyGridInput(body,grid);}
        else if(platformer!=null){double speed=Math.max(0,platformer.number("speed",5));boolean left=actionDown(platformer.get("leftAction","MoveLeft")),right=actionDown(platformer.get("rightAction","MoveRight"));body.vx=left==right?0:(left?-speed:speed);if(actionPressed(platformer.get("jumpAction","Jump"))&&body.grounded)body.vy=-Math.max(.1,platformer.number("jumpSpeed",8));}
        else if(controller!=null){double dx=(actionDown("MoveRight")?1:0)-(actionDown("MoveLeft")?1:0),dy=(actionDown("MoveDown")?1:0)-(actionDown("MoveUp")?1:0);if(!controller.bool("allowArrows",true)){dx=(isDown("D")?1:0)-(isDown("A")?1:0);dy=(isDown("S")?1:0)-(isDown("W")?1:0);}double len=Math.hypot(dx,dy);if(len>0){dx/=len;dy/=len;}double speed=Math.max(0,controller.number("speed",4));body.vx=dx*speed;body.vy=dy*speed;}
        ComponentDef patrol=activeComponent(body,"Patrol");if(patrol!=null&&controller==null&&platformer==null&&grid==null){double speed=Math.max(0,patrol.number("speed",1.5)),distance=Math.max(.05,patrol.number("distance",4));boolean vertical=patrol.get("axis","x").equalsIgnoreCase("y");double position=vertical?body.def.y:body.def.x,origin=vertical?body.originY:body.originX;if(body.patrolDirection>0&&position>=origin+distance)body.patrolDirection=-1;else if(body.patrolDirection<0&&position<=origin)body.patrolDirection=1;if(vertical)body.vy=body.patrolDirection*speed;else body.vx=body.patrolDirection*speed;}
        ComponentDef rigid=activeComponent(body,"Rigidbody2D");if(rigid!=null){double mass=Math.max(.01,rigid.number("mass",1));if(!rigid.bool("freezeY",false))body.vy+=9.81*rigid.number("gravityScale",1)*dt;else body.vy=0;if(rigid.bool("freezeX",false))body.vx=0;double drag=Math.max(0,rigid.number("drag",.4)),factor=Math.max(0,1-(drag/mass)*dt);if(controller==null&&platformer==null&&grid==null&&(patrol==null||patrol.get("axis","x").equalsIgnoreCase("y")))body.vx*=factor;if(controller==null&&platformer==null&&grid==null&&(patrol==null||patrol.get("axis","x").equalsIgnoreCase("x")))body.vy*=factor;double max=Math.max(.1,rigid.number("maxSpeed",12)),speed=Math.hypot(body.vx,body.vy);if(speed>max){body.vx=body.vx/speed*max;body.vy=body.vy/speed*max;}}
    }
    private void applyGridInput(Body body,ComponentDef grid){if(runtimeSeconds<body.gridMoveEnd-1e-9)return;boolean diag=grid.bool("allowDiagonal",false);int dx=0,dy=0;boolean up=actionDown("MoveUp"),down=actionDown("MoveDown"),left=actionDown("MoveLeft"),right=actionDown("MoveRight");boolean just=actionPressed("MoveUp")||actionPressed("MoveDown")||actionPressed("MoveLeft")||actionPressed("MoveRight"),held=up||down||left||right;if(!held){body.gridNextAt=0;return;}if(!just&&runtimeSeconds<body.gridNextAt)return;if(up)dy=-1;else if(down)dy=1;if(left)dx=-1;else if(right)dx=1;if(!diag&&dy!=0)dx=0;if(dx!=0||dy!=0)gridStep(body,dx,dy,grid,true);body.gridNextAt=runtimeSeconds+Math.max(.01,grid.number("repeatDelay",.16));}
    private boolean gridStep(Body body,int dx,int dy,ComponentDef grid,boolean collisionEvent){double step=Math.max(.01,grid.number("step",1)),oldX=body.def.x,oldY=body.def.y,nx=oldX+dx*step,ny=oldY+dy*step;if(grid.bool("snap",true)){nx=Math.rint(nx/step)*step;ny=Math.rint(ny/step)*step;}Block block=blocked(body,nx,ny,nx-oldX,ny-oldY);if(block!=null){markContact(body,nx-oldX,ny-oldY);if(collisionEvent){if(block.other!=null)processContact(body,block.other,true);else fire(body,ScriptProgram.Event.COLLISION,null);}return false;}body.def.x=nx;body.def.y=ny;double duration=Math.max(0,grid.number("moveDuration",0));if(duration>0){body.visualFromX=visualX(body);body.visualFromY=visualY(body);body.gridMoveStart=runtimeSeconds;body.gridMoveEnd=runtimeSeconds+duration;}else{body.visualFromX=nx;body.visualFromY=ny;body.gridMoveStart=body.gridMoveEnd=runtimeSeconds;}return true;}
    private void integrate(Body body,double dt){if(Math.abs(body.vx)>1e-9)moveBody(body,body.vx*dt,0,true);if(Math.abs(body.vy)>1e-9)moveBody(body,0,body.vy*dt,true);}
    private void moveBody(Body body,double dx,double dy,boolean collisionEvent){ComponentDef collider=activeCollider(body);double nx=body.def.x+dx,ny=body.def.y+dy;if(collider==null||!collider.bool("solid",true)){body.def.x=nx;body.def.y=ny;return;}Block block=blocked(body,nx,ny,dx,dy);if(block==null){body.def.x=nx;body.def.y=ny;return;}markContact(body,dx,dy);double oldVx=body.vx,oldVy=body.vy;if(activeComponent(body,"Patrol")!=null)body.patrolDirection*=-1;if(collisionEvent){if(block.other!=null)processContact(body,block.other,true);else fire(body,ScriptProgram.Event.COLLISION,null);}if(dx!=0&&Double.compare(body.vx,oldVx)==0)body.vx=0;if(dy!=0&&Double.compare(body.vy,oldVy)==0)body.vy=0;}
    private void markContact(Body b,double dx,double dy){if(dx>0)b.touchingRight=true;if(dx<0)b.touchingLeft=true;if(dy>0)b.grounded=true;if(dy<0)b.touchingTop=true;syncSensors(b);}
    private Block blocked(Body body,double x,double y,double dx,double dy){ComponentDef collider=activeCollider(body);if(collider==null||!collider.bool("solid",true))return null;double w=colliderWidth(body),h=colliderHeight(body),ox=colliderOffsetX(body),oy=colliderOffsetY(body),ax=x+ox,ay=y+oy;int minX=(int)Math.floor(ax),minY=(int)Math.floor(ay),maxX=(int)Math.floor(ax+w-.001),maxY=(int)Math.floor(ay+h-.001);if((minX<0&&level.boundaryLeft)||(minY<0&&level.boundaryTop)||(maxX>=level.width&&level.boundaryRight)||(maxY>=level.height&&level.boundaryBottom))return new Block(null,null);int sx=Math.max(0,minX),sy=Math.max(0,minY),ex=Math.min(level.width-1,maxX),ey=Math.min(level.height-1,maxY);if(sx<=ex&&sy<=ey)for(TileLayer layer:level.tileLayers){if(!layer.collision||!project.canCollide(body.def.physicsLayer,layer.physicsLayer))continue;for(int ty=sy;ty<=ey;ty++)for(int tx=sx;tx<=ex;tx++){int id=layer.get(tx,ty);if(id<0)continue;TileDef tile=project.getTiles().get(id);if(tile==null||tile.walkable)continue;if(tile.oneWay){double oldBottom=body.def.y+oy+h;if(!(dy>0&&oldBottom<=ty+.08))continue;}return new Block(null,tile);}}for(Body other:bodies.values()){if(other==body||other.destroyed||!other.def.enabled||!project.canCollide(body.def.physicsLayer,other.def.physicsLayer))continue;ComponentDef oc=activeCollider(other);if(oc==null||!oc.bool("solid",true))continue;if(overlaps(ax,ay,w,h,other.def.x+colliderOffsetX(other),other.def.y+colliderOffsetY(other),colliderWidth(other),colliderHeight(other)))return new Block(other,null);}return null;}
    private ComponentDef activeCollider(Body b){ComponentDef c=activeComponent(b,"BoxCollider2D");if(c!=null)return c;return activeComponent(b,"CircleCollider2D");}
    private double colliderWidth(Body b){ComponentDef c=activeCollider(b);if(c==null)return Math.max(.01,b.def.width);return c.type.equals("CircleCollider2D")?Math.max(.01,c.number("radius",.41)*2):Math.max(.01,c.number("width",b.def.width));}
    private double colliderHeight(Body b){ComponentDef c=activeCollider(b);if(c==null)return Math.max(.01,b.def.height);return c.type.equals("CircleCollider2D")?Math.max(.01,c.number("radius",.41)*2):Math.max(.01,c.number("height",b.def.height));}
    private double colliderOffsetX(Body b){ComponentDef c=activeCollider(b);return c==null?0:c.number("offsetX",0);}private double colliderOffsetY(Body b){ComponentDef c=activeCollider(b);return c==null?0:c.number("offsetY",0);}
    private void refreshContactSensors(){for(Body b:bodies.values()){if(b.destroyed||!b.def.enabled||activeCollider(b)==null)continue;b.grounded=b.grounded||blocked(b,b.def.x,b.def.y+.025,0,.025)!=null;b.touchingTop=b.touchingTop||blocked(b,b.def.x,b.def.y-.025,0,-.025)!=null;b.touchingLeft=b.touchingLeft||blocked(b,b.def.x-.025,b.def.y,-.025,0)!=null;b.touchingRight=b.touchingRight||blocked(b,b.def.x+.025,b.def.y,.025,0)!=null;syncSensors(b);}}
    private void syncSensors(Body b){ComponentDef r=b.def.component("Rigidbody2D");if(r==null)return;r.properties.put("grounded",Boolean.toString(b.grounded));r.properties.put("touchingLeft",Boolean.toString(b.touchingLeft));r.properties.put("touchingRight",Boolean.toString(b.touchingRight));r.properties.put("touchingTop",Boolean.toString(b.touchingTop));}
    private void applyTileSurfaceEffects(double dt){for(Body b:bodies.values()){if(b.destroyed||!b.def.enabled)continue;TileDef t=surfaceTile(b);if(t==null)continue;if(t.damage>0&&activeComponent(b,"Health")!=null){b.tileDamageAccumulator+=dt*t.damage;if(b.tileDamageAccumulator>=1){double n=Math.floor(b.tileDamageAccumulator);b.tileDamageAccumulator-=n;applyDamage(b,n,null);}}else b.tileDamageAccumulator=0;if(b.grounded&&t.friction>=0&&t.friction<1)b.vx*=Math.pow(Math.max(.001,t.friction),dt*10);}}
    private TileDef surfaceTile(Body b){int tx=(int)Math.floor(b.def.x+b.def.width/2),ty=(int)Math.floor(b.def.y+colliderHeight(b)+.02);for(TileLayer l:level.tileLayers)if(l.collision){TileDef t=project.getTiles().get(l.get(tx,ty));if(t!=null)return t;}return null;}

    private void resolveInitialPenetrations(){for(int pass=0;pass<4;pass++){boolean changed=false;List<Body>all=new ArrayList<>(bodies.values());for(int i=0;i<all.size();i++)for(int j=i+1;j<all.size();j++){Body a=all.get(i),b=all.get(j);if(solidPair(a,b)&&intersects(a,b)){resolvePenetration(a,b);changed=true;}}if(!changed)break;}}
    private void checkEntityOverlaps(){List<Body>all=new ArrayList<>(bodies.values());for(int i=0;i<all.size();i++)for(int j=i+1;j<all.size();j++){Body a=all.get(i),b=all.get(j);if(a.destroyed||b.destroyed||!a.def.enabled||!b.def.enabled||!project.canCollide(a.def.physicsLayer,b.def.physicsLayer)||!intersects(a,b))continue;boolean solid=solidPair(a,b);processContact(a,b,solid);if(solid&&intersects(a,b))resolvePenetration(a,b);}}
    private boolean solidPair(Body a,Body b){ComponentDef ac=activeCollider(a),bc=activeCollider(b);return ac!=null&&bc!=null&&ac.bool("solid",true)&&bc.bool("solid",true)&&project.canCollide(a.def.physicsLayer,b.def.physicsLayer);}
    private void resolvePenetration(Body a,Body b){double aw=colliderWidth(a),ah=colliderHeight(a),bw=colliderWidth(b),bh=colliderHeight(b),ax=a.def.x+colliderOffsetX(a),ay=a.def.y+colliderOffsetY(a),bx=b.def.x+colliderOffsetX(b),by=b.def.y+colliderOffsetY(b),ox=Math.min(ax+aw,bx+bw)-Math.max(ax,bx),oy=Math.min(ay+ah,by+bh)-Math.max(ay,by);if(ox<=0||oy<=0)return;boolean ma=isMovable(a),mb=isMovable(b);if(!ma&&!mb)return;double eps=.001;if(ox<oy){double dir=(ax+aw/2)<(bx+bw/2)?-1:1,amount=ox+eps;if(ma&&mb){a.def.x+=dir*amount/2;b.def.x-=dir*amount/2;}else if(ma)a.def.x+=dir*amount;else b.def.x-=dir*amount;a.vx=0;b.vx=0;if(dir<0)a.touchingRight=true;else a.touchingLeft=true;}else{double dir=(ay+ah/2)<(by+bh/2)?-1:1,amount=oy+eps;if(ma&&mb){a.def.y+=dir*amount/2;b.def.y-=dir*amount/2;}else if(ma)a.def.y+=dir*amount;else b.def.y-=dir*amount;a.vy=0;b.vy=0;if(dir<0)a.grounded=true;else a.touchingTop=true;}syncSensors(a);syncSensors(b);}
    private boolean isMovable(Body b){return activeComponent(b,"Rigidbody2D")!=null||activeComponent(b,"PlayerController")!=null||activeComponent(b,"PlatformerController")!=null||activeComponent(b,"GridMovement")!=null||activeComponent(b,"Patrol")!=null;}private boolean isPlayerControlled(Body b){return activeComponent(b,"PlayerController")!=null||activeComponent(b,"PlatformerController")!=null||activeComponent(b,"GridMovement")!=null;}
    private void processContact(Body a,Body b,boolean colliderContact){if(!project.canCollide(a.def.physicsLayer,b.def.physicsLayer))return;String key=contactKey(a,b);boolean first=frameContacts.add(key),entered=first&&!contacts.contains(key);if(!entered)return;if(colliderContact){fire(a,ScriptProgram.Event.COLLISION,b);fire(b,ScriptProgram.Event.COLLISION,a);}handlePortal(a,b);handlePortal(b,a);handleTrigger(a,b);handleTrigger(b,a);handleDamage(a,b);handleDamage(b,a);}
    private String contactKey(Body a,Body b){return a.def.id.compareTo(b.def.id)<=0?a.def.id+"\u0000"+b.def.id:b.def.id+"\u0000"+a.def.id;}private boolean intersects(Body a,Body b){return overlaps(a.def.x+colliderOffsetX(a),a.def.y+colliderOffsetY(a),colliderWidth(a),colliderHeight(a),b.def.x+colliderOffsetX(b),b.def.y+colliderOffsetY(b),colliderWidth(b),colliderHeight(b));}private static boolean overlaps(double ax,double ay,double aw,double ah,double bx,double by,double bw,double bh){return ax<bx+bw&&ax+aw>bx&&ay<by+bh&&ay+ah>by;}
    private void handlePortal(Body portal,Body other){ComponentDef p=activeComponent(portal,"ScenePortal");if(p==null||!isPlayerControlled(other)||pendingScene!=null)return;pendingScene=new PendingScene(p.get("targetScene",project.getStartLevel()),p.number("targetX",2),p.number("targetY",2));}
    private void handleTrigger(Body trigger,Body other){ComponentDef t=activeComponent(trigger,"Trigger");if(t==null||!isPlayerControlled(other)||trigger.triggerConsumed)return;fire(trigger,ScriptProgram.Event.TRIGGER,other);if(t.bool("once",false))trigger.triggerConsumed=true;}
    private void handleDamage(Body source,Body target){ComponentDef damage=activeComponent(source,"DamageOnContact"),health=activeComponent(target,"Health");if(damage==null||health==null)return;applyDamage(target,Math.max(0,damage.number("damage",10)),source);}
    private ComponentDef activeComponent(Body body,String type){ComponentDef c=body.def.component(type);return c!=null&&c.bool("enabled",true)?c:null;}private boolean clickable(Body body){ComponentDef c=body.def.component("Clickable");return c==null||c.bool("enabled",true);}
    private void applyDamage(Body target,double amount,Body source){ComponentDef health=activeComponent(target,"Health");if(health==null)return;double max=Math.max(0,health.number("max",100)),current=Math.max(0,health.number("current",max)-Math.max(0,amount));health.properties.put("current",number(current));if(current<=0)destroyBody(target,source);}private void applyHeal(Body target,double amount){ComponentDef health=activeComponent(target,"Health");if(health==null)return;double max=Math.max(0,health.number("max",100)),current=Math.min(max,Math.max(0,health.number("current",max)+Math.max(0,amount)));health.properties.put("current",number(current));}
    private void ensureProgram(Body body){if(body.program==null||!body.scriptSource.equals(body.def.script)){body.scriptSource=body.def.script;body.program=ScriptProgram.compile(body.def.script);}}
    private void fire(Body body,ScriptProgram.Event event,Body other){if(body==null||body.destroyed||!body.def.enabled)return;ensureProgram(body);if(!body.program.validation().valid())return;body.program.fire(event,new ScriptContext(body,other));}
    private void destroyBody(Body body,Body cause){if(body==null||body.destroyed||body.destroying)return;body.destroying=true;fire(body,ScriptProgram.Event.DESTROY,cause);body.destroyed=true;body.destroying=false;}

    private EntityDef resolvePrefabInstance(EntityDef instance){if(instance.prefabKey==null||instance.prefabKey.isBlank())return instance.copy();PrefabDef prefab=project.getPrefabs().get(instance.prefabKey);if(prefab==null||prefab.template==null)return instance.copy();EntityDef base=resolvePrefabTemplate(prefab,new HashSet<>());base=cloneEntity(base,instance.id);base.x=instance.x;base.y=instance.y;base.name=instance.name;base.group=instance.group.isBlank()?base.group:instance.group;base.renderLayer=instance.renderLayer;base.physicsLayer=instance.physicsLayer;base.prefabKey=instance.prefabKey;
        // Preserve components that were explicitly added to the scene instance. Older Studio builds edited
        // the instance directly without creating an override, so dropping these made valid components vanish at runtime.
        for(ComponentDef ic:instance.components)if(base.component(ic.type)==null)base.components.add(ic.copy());
        applyOverrides(base,instance.prefabOverrides);return base;}
    private EntityDef resolvePrefabTemplate(PrefabDef p,Set<String>seen){if(p==null||!seen.add(p.key))return new EntityDef("prefab","Prefab",0,0);EntityDef base=p.parentPrefab.isBlank()?null:resolvePrefabTemplate(project.getPrefabs().get(p.parentPrefab),seen);if(base==null)base=p.template==null?new EntityDef(p.key,p.name,0,0):p.template.copy();else if(p.template!=null)overlayEntity(base,p.template);applyOverrides(base,p.variantOverrides);return base;}
    private static void overlayEntity(EntityDef base,EntityDef child){if(child.assetKey!=null&&!child.assetKey.isBlank())base.assetKey=child.assetKey;base.width=child.width;base.height=child.height;base.renderLayer=child.renderLayer;base.physicsLayer=child.physicsLayer;if(child.script!=null&&!child.script.isBlank())base.script=child.script;for(ComponentDef cc:child.components){base.components.removeIf(c->c.type.equals(cc.type));base.components.add(cc.copy());}base.variables.putAll(child.variables);}
    private void applyOverrides(EntityDef e,Map<String,String>overrides){for(var o:overrides.entrySet())applyEntityOverride(e,o.getKey(),o.getValue());}
    private static void applyEntityOverride(EntityDef e,String path,String value){if(path==null)return;String[]p=path.split("\\.");if(p.length==1){switch(p[0]){case"name"->e.name=value;case"asset","sprite","assetKey"->e.assetKey=value;case"width"->{try{e.width=Double.parseDouble(value);}catch(Exception ignored){}}case"height"->{try{e.height=Double.parseDouble(value);}catch(Exception ignored){}}case"renderLayer"->e.renderLayer=value;case"physicsLayer"->e.physicsLayer=value;default->e.variables.put(p[0],value);}}else{ComponentDef c=e.component(p[0]);if(c!=null)c.properties.put(p[1],value);}}
    private void createEntity(Body source,String templateRef,Double x,Double y){if(level==null||templateRef==null||templateRef.isBlank())return;PrefabDef prefab=project.getPrefabs().get(templateRef);if(prefab==null)prefab=project.getPrefabs().values().stream().filter(p->p.name.equalsIgnoreCase(templateRef)).findFirst().orElse(null);if(prefab!=null&&prefab.template!=null){createPrefab(source,prefab,x,y);return;}EntityDef template=level.entities.stream().filter(e->e.id.equals(templateRef)).findFirst().orElseGet(()->level.entities.stream().filter(e->e.name.equalsIgnoreCase(templateRef)).findFirst().orElse(null));if(template==null){logger.accept("[Script] create: no existe la entidad o prefab '"+templateRef+"'.");return;}spawnResolved(source,resolvePrefabInstance(template),x,y);}
    private void createPrefab(Body source,String ref,Double x,Double y){PrefabDef p=project.getPrefabs().get(ref);if(p==null)p=project.getPrefabs().values().stream().filter(v->v.name.equalsIgnoreCase(ref)).findFirst().orElse(null);if(p==null||p.template==null){logger.accept("[Script] spawnPrefab: no existe el prefab de entidad '"+ref+"'.");return;}createPrefab(source,p,x,y);}
    private void createPrefab(Body source,PrefabDef p,Double x,Double y){EntityDef template=resolvePrefabTemplate(p,new HashSet<>());template.prefabKey=p.key;spawnResolved(source,template,x,y);}
    private void spawnResolved(Body source,EntityDef template,Double x,Double y){String id=uniqueRuntimeId(template.id);EntityDef def=cloneEntity(template,id);def.x=x==null?(source==null?template.x:source.def.x):x;def.y=y==null?(source==null?template.y:source.def.y):y;Body body=new Body(def);normalizeHealth(body);normalizeGrid(body);bodies.put(def.id,body);fire(body,ScriptProgram.Event.START,null);}
    private String uniqueRuntimeId(String base){String clean=base==null||base.isBlank()?"entity":base,id;do{id=clean+"#"+(++runtimeEntitySequence);}while(bodies.containsKey(id));return id;}private static EntityDef cloneEntity(EntityDef source,String id){EntityDef c=new EntityDef(id,source.name,source.x,source.y);c.width=source.width;c.height=source.height;c.enabled=source.enabled;c.layer=source.layer;c.group=source.group;c.renderLayer=source.renderLayer;c.physicsLayer=source.physicsLayer;c.assetKey=source.assetKey;c.script=source.script;c.prefabKey=source.prefabKey;source.components.forEach(x->c.components.add(x.copy()));c.variables.putAll(source.variables);c.prefabOverrides.putAll(source.prefabOverrides);return c;}

    private void updateAnimator(Body b,double dt){ComponentDef a=activeComponent(b,"Animator");if(a==null)return;String desired=a.get("state","");AnimatorController controller=project.getAnimatorControllers().get(a.get("controller",""));if(controller!=null){ensureAnimatorParameters(b,controller);if(desired.isBlank())desired=controller.defaultState;evaluateTransitions(b,a,controller,desired);desired=a.get("state",desired);}AnimatorState state=controller==null?null:controller.states.get(desired);String clipKey=resolveAnimatorClip(b,a,state,desired);if(clipKey.isBlank())clipKey=a.get("clip","");if(clipKey.isBlank())return;if(!Objects.equals(b.animationClip,clipKey))startAnimation(b,a,clipKey);if(!b.animationPlaying)return;AnimationClip clip=project.getAnimationClips().get(b.animationClip);if(clip==null||clip.frames.isEmpty())return;double stateSpeed=state==null?1:Math.max(0,state.speed),speed=Math.max(0,a.number("speed",1))*Math.max(0,clip.speed)*stateSpeed;b.frameElapsed+=dt*speed;int guard=0;while(guard++<100&&b.frameElapsed>=clip.frameDuration(Math.max(0,Math.min(clip.frames.size()-1,b.animationFrame)))){b.frameElapsed-=clip.frameDuration(b.animationFrame);int old=b.animationFrame;b.animationFrame+=b.animationDirection;if(b.animationFrame>=clip.frames.size()||b.animationFrame<0){if(clip.pingPong&&clip.frames.size()>1){b.animationDirection*=-1;b.animationFrame=Math.max(0,Math.min(clip.frames.size()-1,b.animationFrame+2*b.animationDirection));fire(b,ScriptProgram.Event.ANIMATIONLOOP,null);}else if(clip.loop){b.animationFrame=b.animationDirection>0?0:clip.frames.size()-1;fire(b,ScriptProgram.Event.ANIMATIONLOOP,null);}else{b.animationFrame=Math.max(0,Math.min(clip.frames.size()-1,b.animationFrame));b.animationPlaying=false;a.properties.put("finished","true");fire(b,ScriptProgram.Event.ANIMATIONEND,null);if(!b.queuedAnimation.isBlank()){String q=b.queuedAnimation;b.queuedAnimation="";playAnimation(b,q);}break;}}if(old!=b.animationFrame){b.frameHitTargets.clear();String event=clip.frames.get(b.animationFrame).event;if(event!=null&&!event.isBlank()){fireNamed(b,"animation:"+event,null);emitWorldEvent("animation:"+event);}}}a.properties.put("frame",Integer.toString(b.animationFrame));}
    private void ensureAnimatorParameters(Body b,AnimatorController c){if(Objects.equals(b.animatorControllerKey,c.key))return;b.animatorControllerKey=c.key;b.animatorParameters.clear();for(AnimatorParameter p:c.parameters.values())b.animatorParameters.put(p.name,p.defaultValue);}
    private String resolveAnimatorClip(Body b,ComponentDef a,AnimatorState state,String desired){String clip=state==null?"":state.clipKey;if(state!=null&&state.blendTree.type!=BlendTreeType.NONE&&!state.blendTree.children.isEmpty()){double x=animatorParamNumber(b,state.blendTree.parameterX),y=animatorParamNumber(b,state.blendTree.parameterY);BlendChild best=null;double dist=Double.MAX_VALUE;for(BlendChild child:state.blendTree.children){double d=state.blendTree.type==BlendTreeType.ONE_D?Math.abs(x-child.x):Math.hypot(x-child.x,y-child.y);if(d<dist){dist=d;best=child;}}if(best!=null&&!best.clipKey.isBlank())clip=best.clipKey;}AnimationSet set=project.getAnimationSets().get(a.get("animationSet",""));if(set!=null){String dir=directionFor(b,set.directionMode);a.properties.put("direction",dir);String mapped=set.clip(desired,dir);if(!mapped.isBlank())clip=mapped;else if(set.useFlipX&&dir.equals("RIGHT")){String left=set.clip(desired,"LEFT");if(!left.isBlank()){clip=left;a.properties.put("flipX","true");}}else if(set.useFlipX&&dir.equals("LEFT"))a.properties.put("flipX","false");}return clip==null?"":clip;}
    private String directionFor(Body b,DirectionMode mode){double x=b.vx,y=b.vy;if(Math.hypot(x,y)<1e-6)return b.lastAnimationDirection;String d;if(mode==DirectionMode.TWO)d=x<0?"LEFT":"RIGHT";else if(mode==DirectionMode.FOUR)d=Math.abs(x)>Math.abs(y)?(x<0?"LEFT":"RIGHT"):(y<0?"UP":"DOWN");else{double ax=Math.abs(x),ay=Math.abs(y);if(ax>ay*2)d=x<0?"LEFT":"RIGHT";else if(ay>ax*2)d=y<0?"UP":"DOWN";else d=(y<0?"UP_":"DOWN_")+(x<0?"LEFT":"RIGHT");}b.lastAnimationDirection=d;return d;}
    private double animatorParamNumber(Body b,String name){try{return Double.parseDouble(b.animatorParameters.getOrDefault(name,"0"));}catch(Exception e){return 0;}}
    private String transitionValue(Body b,String path){if(path!=null&&path.toLowerCase(Locale.ROOT).startsWith("param."))return b.animatorParameters.getOrDefault(path.substring(6),"0");return readEntityPath(path,b,null);}
    private void consumeTrigger(Body b,AnimatorController c,String path){if(path==null||!path.toLowerCase(Locale.ROOT).startsWith("param."))return;String name=path.substring(6);AnimatorParameter p=c.parameters.get(name);if(p!=null&&p.type==AnimatorParameterType.TRIGGER)b.animatorParameters.put(name,"false");}
    private void evaluateTransitions(Body b,ComponentDef animator,AnimatorController c,String current){for(AnimatorTransition t:c.transitions.stream().sorted(Comparator.comparingInt(x->x.priority)).toList()){if(!(t.from.equalsIgnoreCase(current)||t.from.equalsIgnoreCase("Any")||t.from.equalsIgnoreCase("AnyState")))continue;if(t.exitTime>=0&&animationProgress(b)<t.exitTime)continue;if(t.path.isBlank()||compare(transitionValue(b,t.path),t.value,t.operator)){animator.properties.put("state",t.to);consumeTrigger(b,c,t.path);break;}}}
    private double animationProgress(Body b){AnimationClip c=project.getAnimationClips().get(b.animationClip);if(c==null||c.frames.isEmpty())return 0;double elapsed=0;if(b.animationDirection>=0){for(int i=0;i<b.animationFrame&&i<c.frames.size();i++)elapsed+=c.frameDuration(i);elapsed+=b.frameElapsed;}else{for(int i=c.frames.size()-1;i>b.animationFrame;i--)elapsed+=c.frameDuration(i);elapsed+=b.frameElapsed;}return c.duration()<=0?0:elapsed/c.duration();}
    private void startAnimation(Body b,ComponentDef a,String clipKey){AnimationClip clip=project.getAnimationClips().get(clipKey);if(clip==null||clip.frames.isEmpty()){a.properties.put("finished","true");return;}b.animationClip=clipKey;if(clip.randomStart)b.animationFrame=ThreadLocalRandom.current().nextInt(clip.frames.size());else b.animationFrame=clip.reverse?clip.frames.size()-1:0;b.animationDirection=clip.reverse?-1:1;b.frameElapsed=0;b.animationPlaying=true;b.frameHitTargets.clear();a.properties.put("clip",clipKey);a.properties.put("frame",Integer.toString(b.animationFrame));a.properties.put("finished","false");fire(b,ScriptProgram.Event.ANIMATIONSTART,null);}
    private void playAnimation(Body b,String clipOrState){ComponentDef a=b==null?null:b.def.component("Animator");if(a==null&&b!=null){a=ComponentDef.preset("Animator");b.def.components.add(a);}if(a==null)return;AnimatorController c=project.getAnimatorControllers().get(a.get("controller",""));if(c!=null&&c.states.containsKey(clipOrState)){a.properties.put("state",clipOrState);b.animationClip="";}else startAnimation(b,a,clipOrState);}
    private void queueAnimation(Body b,String clipOrState){if(b!=null)b.queuedAnimation=clipOrState==null?"":clipOrState;}private void stopAnimation(Body b){if(b==null)return;b.animationPlaying=false;ComponentDef a=b.def.component("Animator");if(a!=null)a.properties.put("finished","true");}
    private String animatedAsset(Body b){ComponentDef a=activeComponent(b,"Animator");if(a!=null&&!b.animationClip.isBlank()){AnimationClip c=project.getAnimationClips().get(b.animationClip);if(c!=null&&!c.frames.isEmpty())return c.frames.get(Math.max(0,Math.min(c.frames.size()-1,b.animationFrame))).assetKey;}return b.def.assetKey;}
    private String animatedTileAsset(TileDef t){if(t.animationClip==null||t.animationClip.isBlank())return t.assetKey;AnimationClip c=project.getAnimationClips().get(t.animationClip);if(c==null||c.frames.isEmpty())return t.assetKey;double total=c.duration();if(total<=0)return c.frames.getFirst().assetKey;double time=c.loop?runtimeSeconds%total:Math.min(runtimeSeconds,total-.0001),sum=0;for(AnimationFrame f:c.frames){sum+=f.duration;if(time<sum)return f.assetKey;}return c.frames.getLast().assetKey;}

    private void updateParticles(Body b,double dt){
        ComponentDef e=activeComponent(b,"ParticleEmitter2D");
        boolean playing=e!=null&&e.bool("playing",true);
        if(!playing){if(b.particlePlayingLast)resetParticleEmitter(b);b.particlePlayingLast=false;return;}
        String ref=e.get("preset","");
        ParticlePreset p=project.particlePreset(ref);
        if(p==null){
            if(!Objects.equals(b.particleMissingRef,ref)){logger.accept("[Partículas] No existe el preset '"+ref+"' usado por "+b.def.name+".");b.particleMissingRef=ref;}
            resetParticleEmitter(b);b.particlePlayingLast=true;return;
        }
        b.particleMissingRef="";
        if(!Objects.equals(b.particlePresetKey,p.key)||!b.particlePlayingLast){resetParticleEmitter(b);b.particlePresetKey=p.key;}
        b.particlePlayingLast=true;
        if(p.burst&&!b.particleBurstDone){
            int requested=Math.max(0,p.burstCount),count=Math.min(requested,MAX_PARTICLES_PER_EMITTER_FRAME);
            for(int i=0;i<count;i++)if(!spawnParticle(b,p))break;
            if(requested>count)warnParticleLimit(b,p,"Burst limitado a "+MAX_PARTICLES_PER_EMITTER_FRAME+" partículas por activación.");
            b.particleBurstDone=true;
        }
        if(!p.burst){
            b.particleAccumulator+=Math.max(0,p.rate)*Math.max(0,dt);
            long due=(long)Math.floor(b.particleAccumulator);b.particleAccumulator-=due;
            int count=(int)Math.min(due,MAX_PARTICLES_PER_EMITTER_FRAME);
            for(int i=0;i<count;i++)if(!spawnParticle(b,p))break;
            if(due>count)warnParticleLimit(b,p,"Emisión por frame limitada a "+MAX_PARTICLES_PER_EMITTER_FRAME+" partículas.");
        }
    }
    private void resetParticleEmitter(Body b){b.particleBurstDone=false;b.particleAccumulator=0;b.particlePresetKey="";b.particleLimitWarned=false;}
    private void warnParticleLimit(Body b,ParticlePreset p,String detail){if(b.particleLimitWarned)return;b.particleLimitWarned=true;logger.accept("[Partículas] "+detail+" Emisor: "+b.def.name+", preset: "+p.key+".");}
    private boolean spawnParticle(Body b,ParticlePreset p){
        if(particles.size()>=MAX_LIVE_PARTICLES){warnParticleLimit(b,p,"Se alcanzó el límite global de "+MAX_LIVE_PARTICLES+" partículas vivas; se descartará emisión nueva.");return false;}
        double angle=Math.toRadians(p.direction+(ThreadLocalRandom.current().nextDouble()-.5)*Math.max(0,p.spread));
        double speed=Math.max(0,p.speed)*(.75+ThreadLocalRandom.current().nextDouble()*.5),vx=Math.cos(angle)*speed,vy=Math.sin(angle)*speed;
        double originX=visualX(b)+b.def.width/2,originY=visualY(b)+b.def.height/2;
        if(p.localSpace)particles.add(new Particle(p,b,true,0,0,vx,vy));else particles.add(new Particle(p,b,false,originX,originY,vx,vy));
        return true;
    }
