    private void checkAnimationHitboxes(){List<Body>live=bodies.values().stream().filter(b->!b.destroyed&&b.def.enabled).toList();for(Body attacker:live){List<FrameShape>hits=frameShapes(attacker,FrameShapeRole.HITBOX);if(hits.isEmpty())continue;for(Body target:live){if(target==attacker||attacker.frameHitTargets.contains(target.def.id))continue;List<FrameShape>hurts=frameShapes(target,FrameShapeRole.HURTBOX);if(hurts.isEmpty())continue;boolean overlap=false;for(FrameShape h:hits)for(FrameShape u:hurts)if(intersects(shapeRect(attacker,h),shapeRect(target,u))){overlap=true;break;}if(!overlap)continue;attacker.frameHitTargets.add(target.def.id);fireNamed(attacker,"hitbox",target);fireNamed(target,"hurtbox",attacker);emitWorldEvent("animationHit");ComponentDef damage=activeComponent(attacker,"DamageOnContact");if(damage!=null)applyDamage(target,Math.max(0,damage.number("damage",0)),attacker);}}}
