    private String readEntityPath(String path,Body self,Body other){String[]p=path.split("\.");if(p.length==0)return"";Body target=self;int i=0;if(p[0].equalsIgnoreCase("self")||p[0].equalsIgnoreCase("this")){target=self;i=1;}else if(p[0].equalsIgnoreCase("other")){target=other;i=1;}else if(p.length>=2){Body named=resolveBody(p[0],self,other);if(named!=null){target=named;i=1;}}if(target==null)return"";if(i>=p.length)return"";if(i+2<p.length&&p[i].equalsIgnoreCase("Animator")&&p[i+1].equalsIgnoreCase("param"))return target.animatorParameters.getOrDefault(p[i+2],"0");if(i+1<p.length){ComponentDef c=target.def.component(p[i]);if(c!=null)return c.get(p[i+1],"");}return bodyProperty(target,p[i]);}
